# Generated by scripts/homebrew-formulas.py in tinhthanh/shipyard for v0.3.31-fork.8.
class Vetgo < Formula
  desc "Run coding agents on your own boxes: the berth CLI and laptop agent"
  homepage "https://github.com/tinhthanh/shipyard"
  version "0.3.31-fork.8"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.8/berth-darwin-arm64.tar.gz"
      sha256 "0140601300f9124a0d8c9e9aefbdbd1eb76dc95f8b55873dbf62be0b77afe4ba"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.8/berth-darwin-amd64.tar.gz"
      sha256 "d214f4e8a17c80e340434f6ced6986fcac5e83b6a3321d54528095166c63b6c9"
    end

    # The berthd builds `berth upgrade` puts on Mac boxes; the Linux ones
    # come in berth's own archive.
    resource "berthd-darwin-arm64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.8/berthd-darwin-arm64.tar.gz"
      sha256 "32efcae8759a31b079f86a9e9cf51bf00a300a802142da0ef8c6fac5b6dacdfc"
    end
    resource "berthd-darwin-amd64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.8/berthd-darwin-amd64.tar.gz"
      sha256 "8256f1d00f2d642e40d736ac7855a8f6be5e657e6708d76a1989a6e7b3ff5ecc"
    end
  end
  on_linux do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.8/berth-linux-arm64.tar.gz"
      sha256 "3e9df1d5b164e474cf7257725d3c7a60a751e9f997363052c1ed233db1c7e6d1"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.8/berth-linux-amd64.tar.gz"
      sha256 "7972981753847f7f529d16ddcf1cbb5ec4ec192eb770ff07ba1585827b6527ed"
    end
  end

  def install
    # berth looks beside its own file (through the link in bin) for the
    # berthd and tmux builds it uploads to boxes.
    libexec.install Dir["*"]
    if OS.mac?
      %w[arm64 amd64].each do |arch|
        resource("berthd-darwin-#{arch}").stage { libexec.install "berthd" => "berthd-darwin-#{arch}" }
      end
    end
    bin.install_symlink libexec/"berth"
  end

  def caveats
    <<~EOS
      Start the laptop agent, and have it start when you log in:
        berth agent install
      Add a box: berth add ssh USER@HOST (see berth help).
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/berth version")
  end
end
